#include <NexumDesign.h>
#include "NexumFxProcessor.h"
#include "FxPage.h"
#include "SynthSidebar.h"
#include <BinaryData.h>
namespace noctrl {
class NexumFxEditor:public juce::AudioProcessorEditor,private juce::Timer,public juce::DragAndDropContainer {
 NexumFxProcessor& p;OscModernTheme theme;SynthSidebar sidebar{p,2,"FX"};nxf::SidebarTab rackTab{"FX"},libraryTab{"LIBRARY"};FxPage page;AutomationSlider output;juce::Label outputLabel;juce::TextButton bypass{"BYPASS"};
 std::unique_ptr<juce::AudioProcessorValueTreeState::SliderAttachment> gainLink;std::unique_ptr<juce::AudioProcessorValueTreeState::ButtonAttachment> bypassLink;
 juce::Image logo;juce::TooltipWindow tooltip{this,600};
 void timerCallback()override{sidebar.refreshMacros();bypass.setColour(juce::TextButton::textColourOnId,UiStyle::blue());bypass.setColour(juce::TextButton::textColourOffId,nd::colour(juce::Colour(0xff91a7b9)));repaint();}
public:
 NexumFxEditor(NexumFxProcessor& processor):AudioProcessorEditor(processor),p(processor),page(p,true){using namespace juce;setLookAndFeel(&theme);theme.attach(*this,"Nexum FX");logo=ImageCache::getFromMemory(BinaryData::NEXUM_FX_png,BinaryData::NEXUM_FX_pngSize);addAndMakeVisible(page);addAndMakeVisible(output);addAndMakeVisible(outputLabel);addAndMakeVisible(bypass);outputLabel.setText("OUTPUT",dontSendNotification);outputLabel.setFont(FontOptions(nd::number("fontSize",9),Font::bold));outputLabel.setColour(Label::textColourId,nd::colour(Colour(0xff91a7b9)));outputLabel.setJustificationType(Justification::centred);output.setSliderStyle(Slider::RotaryHorizontalVerticalDrag);output.setTextBoxStyle(Slider::TextBoxBelow,false,72,16);output.bindAutomation(p.state.getParameter("fxOutput"),&p);output.getProperties().set("parameterIndex",p.state.getParameter("fxOutput")->getParameterIndex());output.textFromValueFunction=[](double v){return String(v,1)+" dB";};output.setDoubleClickReturnValue(true,0);gainLink=std::make_unique<AudioProcessorValueTreeState::SliderAttachment>(p.state,"fxOutput",output);output.textFromValueFunction=[](double v){return String(v,1)+" dB";};output.updateText();output.setTooltip("Output gain / right-click: host automation");bypass.setClickingTogglesState(true);bypass.setTooltip("Whole rack bypass. Blue: bypass active.");bypass.getProperties().set("parameterIndex",p.state.getParameter("fxBypass")->getParameterIndex());bypass.setColour(TextButton::buttonColourId,nd::colour(Colour(0xff0c1822)));bypass.setColour(TextButton::buttonOnColourId,nd::colour(Colour(0xff0c1822)));bypassLink=std::make_unique<AudioProcessorValueTreeState::ButtonAttachment>(p.state,"fxBypass",bypass);addAndMakeVisible(sidebar);sidebar.setLogo(logo);sidebar.getProperties().set("completeBrandLogo",true);sidebar.addAndMakeVisible(rackTab);sidebar.addAndMakeVisible(libraryTab);rackTab.setToggleState(true,dontSendNotification);rackTab.onClick=[this]{page.setVisible(true);};libraryTab.onClick=[this]{for(auto* child:page.getChildren())if(child->getComponentID()=="fx-library-open")if(auto* button=dynamic_cast<juce::Button*>(child))button->triggerClick();};setSize(1332,720);timerCallback();startTimerHz(25);}
 ~NexumFxEditor()override{stopTimer();gainLink.reset();bypassLink.reset();setLookAndFeel(nullptr);}
 void resized()override{sidebar.setBounds(0,0,92,getHeight());rackTab.setBounds(0,67,92,38);libraryTab.setBounds(0,105,92,38);page.setBounds(108,78,1208,getHeight()-94);bypass.setBounds(954,21,110,28);outputLabel.setBounds(1084,2,90,12);output.setBounds(1084,14,90,48);}
 int getControlParameterIndex(juce::Component& control)override{for(auto* c=&control;c&&c!=this;c=c->getParentComponent())if(c->getProperties().contains("parameterIndex"))return (int)c->getProperties()["parameterIndex"];return -1;}
 void paint(juce::Graphics& g)override{nd::Scope suitScope("controls");using namespace juce;g.fillAll(UiStyle::canvas());g.setColour(Colour(0xff17212a));g.fillRect(92,0,getWidth()-92,66);g.setColour(Colour(0xff344650));g.drawHorizontalLine(66,92.f,(float)getWidth());for(int c=0;c<2;++c){float x=1202.f+c*32;float db=Decibels::gainToDecibels(p.masterMeters[c].load(),-90.f);g.setFont(FontOptions(nd::number("fontSize",9),Font::bold));g.setColour(nd::colour(nd::colour(Colour(0xff91a7b9))));g.drawText(c==0?"L":"R",(int)x-5,3,20,12,Justification::centred);g.setColour(nd::colour(nd::colour(Colour(0xff07121b))));g.fillRect(x,18.f,9.f,30.f);float h=jlimit(0.f,1.f,(db+60)/60)*30;g.setColour(nd::colour(db>0?nd::colour(Colour(0xffff9d58)):UiStyle::blue()));g.fillRect(x,48-h,9.f,h);g.setColour(nd::colour(nd::colour(Colour(0xffb6cada))));g.setFont(FontOptions(nd::number("fontSize",8.5f)));g.drawText(db<=-90?"-inf":String(db,1),(int)x-11,50,32,12,Justification::centred);}}
};
juce::AudioProcessorEditor* NexumFxProcessor::createEditor(){return new NexumFxEditor(*this);}
}
